   449  aiReturn aiMaterial::AddBinaryProperty(const void *pInput,
   450          unsigned int pSizeInBytes,
   451          const char *pKey,
   452          unsigned int type,
   453          unsigned int index,
   454          aiPropertyTypeInfo pType) {
   455      ai_assert(pInput != nullptr);
   456      ai_assert(pKey != nullptr);
   457      ai_assert(0 != pSizeInBytes);
   458
   459      if (0 == pSizeInBytes) {
   460          return AI_FAILURE;
   461      }
   462
   463      // first search the list whether there is already an entry with this key
   464      unsigned int iOutIndex(UINT_MAX);
   465      for (unsigned int i = 0; i < mNumProperties; ++i) {
   466          aiMaterialProperty *prop(mProperties[i]);
   467
   468          if (prop /* just for safety */ && !strcmp(prop->mKey.data, pKey) &&
   469                  prop->mSemantic == type && prop->mIndex == index) {
   470
   471              delete mProperties[i];
   472              iOutIndex = i;
   473          }
   474      }
   475
   476      // Allocate a new material property
   477      aiMaterialProperty *pcNew = new aiMaterialProperty();
   478
   479      // .. and fill it
   480      pcNew->mType = pType;
   481      pcNew->mSemantic = type;
   482      pcNew->mIndex = index;
   483
   484      pcNew->mDataLength = pSizeInBytes;
   485      pcNew->mData = new char[pSizeInBytes];
   486      memcpy(pcNew->mData, pInput, pSizeInBytes);
   487
   488      pcNew->mKey.length = static_cast<ai_uint32>(::strlen(pKey));
   489      ai_assert(MAXLEN > pcNew->mKey.length);
   490      strcpy(pcNew->mKey.data, pKey);
   491
   492      if (UINT_MAX != iOutIndex) {
   493          mProperties[iOutIndex] = pcNew;
   494          return AI_SUCCESS;
   495      }
   496
   497      // resize the array ... double the storage allocated
   498      if (mNumProperties == mNumAllocated) {
   499          const unsigned int iOld = mNumAllocated;
   500          mNumAllocated *= 2;
   501
   502          aiMaterialProperty **ppTemp;
   503          try {
   504              ppTemp = new aiMaterialProperty *[mNumAllocated];
   505          } catch (std::bad_alloc &) {
   506              delete pcNew;
   507              return AI_OUTOFMEMORY;
   508          }
   509
   510          // just copy all items over; then replace the old array
   511          memcpy(ppTemp, mProperties, iOld * sizeof(void *));
   512
   513          delete[] mProperties;
   514          mProperties = ppTemp;
   515      }
   516      // push back ...
   517      mProperties[mNumProperties++] = pcNew;
   518
   519      return AI_SUCCESS;
   520  }
